// Se crea un registro nuevo en blanco y se asigna al formulario
var nuevoRegistro = new VRegister( theRoot );
nuevoRegistro.setTable( theRegisterIn.tableInfo().idRef() );
var formulario = theRoot.dataView();
formulario.setRegister( nuevoRegistro );
formulario.setFocusToFirst();

#include "(CurrentProject)/js/interface/deshabilitarControles.js"

var formulario = theRoot.dataView();
deshabilitaControles(formulario);

// Deshabilitamos también el separador de pestañas
formulario.control("SEP").enabled = false;

// Habilitamos los botones editar y cancelar
formulario.control("BTN_CNC").enabled = true;
formulario.control("BTN_EDT").enabled = true;
